import java.util.Arrays;

class BubbleSort {

    private static final int[] SAMPLE_VALUES = { 64, 34, 25, 12, 22, 11, 90 };

    private BubbleSort() {
    }

    public static void sort(int[] values) {
        if (values == null || values.length < 2) {
            return;
        }

        for (int end = values.length - 1; end > 0; end--) {
            boolean swapped = false;

            for (int index = 0; index < end; index++) {
                if (values[index] > values[index + 1]) {
                    swap(values, index, index + 1);
                    swapped = true;
                }
            }

            if (!swapped) {
                break;
            }
        }
    }

    private static void swap(int[] values, int leftIndex, int rightIndex) {
        int temp = values[leftIndex];
        values[leftIndex] = values[rightIndex];
        values[rightIndex] = temp;
    }

    public static void main(String[] args) {
        int[] values = SAMPLE_VALUES.clone();
        sort(values);
        System.out.println("Sorted array: " + Arrays.toString(values));
    }
}

